sp_widget.script:
(function() { data.logs = []; data.filter = input ? input.filter || "" : "";
  try { var gr = new GlideRecord("x_1433041_identi_0_audit_event"); if (data.filter) gr.addQuery("event_type", data.filter);
    gr.orderByDesc("performed_at"); gr.setLimit(50); gr.query();
    while (gr.next()) { data.logs.push({ sys_id: gr.getValue("sys_id"), event_type: gr.getDisplayValue("event_type"), description: gr.getValue("description"), performed_by: gr.getDisplayValue("performed_by"), performed_at: gr.getDisplayValue("performed_at"), severity: gr.getValue("severity"), application: gr.getDisplayValue("application") }); }
  } catch (e) { gs.error("IBAR Audit Log Table widget error: " + e.message); }
})();
